// src/App.js
import React from 'react';
import AcademicBackground from './components/AcademicBackground';
import WorkExperience from './components/WorkExperience';
import Projects from './components/Projects';
import './App.css';

function App() {
  return (
    <div className="App">
      <header>
        <h1>Jake Lee</h1>
      </header>
      <main>
      <nav>
          <a href="#academic-background">Academic Background</a><br />
          <a href="#work-experience">Work Experience</a><br />
          <a href="#projects">Projects</a><br />
        </nav>
        <AcademicBackground />
        <WorkExperience />
        <Projects />
      </main>
      <footer>
        <p>© 2024 Jake Lee</p>
      </footer>
    </div>
  );
}

export default App;
